        self.targets=None; self.browserslist=False; self.bundle=False; self.custom_media=False
        self.error_recovery=False; self.css_modules=False; self.css_modules_file=None
        self.css_modules_pattern=None; self.css_modules_dashed_idents=False; self.inputs=[]

def eprint(s):
