def clap_unknown(arg):
    eprint(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n")
    eprint(f"\tIf you tried to supply `{arg}` as a value rather than a flag, use `-- {arg}`\n")
    eprint("USAGE:\n    executable [OPTIONS] [INPUT_FILE]...\n")
    eprint("For more information try --help")
    return 2

def missing_value(name, metav):
    eprint(f"error: The argument '{name} <{metav}>' requires a value but none was supplied\n")
    eprint("For more information try --help")
    return 2

def parse_args(argv):
    opts=Opts(); i=0; after=False
    val_flags={"--output-file":("output_file","OUTPUT_FILE"),"-o":("output_file","OUTPUT_FILE"),
               "--output-dir":("output_dir","OUTPUT_DIR"),"-d":("output_dir","OUTPUT_DIR"),
               "--targets":("targets","TARGETS"),"-t":("targets","TARGETS"),
               "--css-modules-pattern":("css_modules_pattern","CSS_MODULES_PATTERN")}
    while i < len(argv):
        a=argv[i]
        if after:
            opts.inputs.append(a); i+=1; continue
        if a == "--": after=True; i+=1; continue
        if a in ("-h","--help"):
            sys.stdout.write(HELP); return None,0
        if a in ("-V","--version"):
            print(VERSION); return None,0
        if a in ("-m","--minify"):
            opts.minify=True; i+=1; continue
        if a == "--sourcemap": opts.sourcemap=True; i+=1; continue
        if a == "--browserslist": opts.browserslist=True; i+=1; continue
        if a == "--bundle": opts.bundle=True; i+=1; continue
        if a == "--custom-media": opts.custom_media=True; i+=1; continue
        if a == "--error-recovery": opts.error_recovery=True; i+=1; continue
        if a == "--css-modules-dashed-idents": opts.css_modules_dashed_idents=True; i+=1; continue
        if a.startswith("--output-file="):
            opts.output_file=a.split("=",1)[1]; i+=1; continue
        if a.startswith("--output-dir="):
            opts.output_dir=a.split("=",1)[1]; i+=1; continue
        if a.startswith("--targets="):
            opts.targets=a.split("=",1)[1]; i+=1; continue
        if a.startswith("--css-modules-pattern="):
            opts.css_modules_pattern=a.split("=",1)[1]; i+=1; continue
        if a.startswith("--css-modules="):
            opts.css_modules=True; opts.css_modules_file=a.split("=",1)[1]; i+=1; continue
        if a == "--css-modules":
            opts.css_modules=True
            if i+1 < len(argv) and not argv[i+1].startswith('-'):
                opts.css_modules_file=argv[i+1]; i+=2
            else:
