    if opts.output_file and opts.output_dir:
        eprint("error: The argument '--output-file <OUTPUT_FILE>' cannot be used with '--output-dir <OUTPUT_DIR>'\n")
        eprint("USAGE:\n    executable <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>\n")
        eprint("For more information try --help")
        return None,2
    if opts.sourcemap and not (opts.output_file or opts.output_dir):
