# ---------------- CSS parsing helpers ----------------
def remove_non_bang_comments(css):
    out=[]; i=0; n=len(css); in_s=None; esc=False
    while i<n:
        c=css[i]
        if in_s:
            out.append(c)
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_s: in_s=None
            i+=1; continue
        if c in ('"',"'"):
            in_s=c; out.append(c); i+=1; continue
        if c=='/' and i+1<n and css[i+1]=='*':
            j=css.find('*/', i+2)
            if j<0: break
            if i+2<n and css[i+2]=='!':
                out.append(css[i:j+2])
            else:
                out.append(' ')
            i=j+2; continue
        out.append(c); i+=1
    return ''.join(out)

def find_matching(s, start, open_ch='{', close_ch='}'):
    depth=0; in_s=None; esc=False; par=0
    for i in range(start, len(s)):
        c=s[i]
        if in_s:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_s: in_s=None
            continue
        if c in ('"',"'"):
            in_s=c; continue
        if c==open_ch:
            depth+=1
        elif c==close_ch:
            depth-=1
            if depth==0: return i
    return len(s)-1

def first_top_level(s, chars):
    depth=0; in_s=None; esc=False
    for i,c in enumerate(s):
        if in_s:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_s: in_s=None
            continue
        if c in ('"',"'"):
            in_s=c; continue
        if c in '([{': depth+=1
        elif c in ')]}': depth=max(0, depth-1)
        elif depth==0 and c in chars: return i,c
    return -1,''

def split_top(s, sep=';'):
    parts=[]; start=0; depth=0; in_s=None; esc=False
    for i,c in enumerate(s):
        if in_s:
            if esc: esc=False
            elif c=='\\': esc=True
            elif c==in_s: in_s=None
            continue
        if c in ('"',"'"):
            in_s=c; continue
        if c in '([{': depth+=1
        elif c in ')]}': depth=max(0, depth-1)
        elif c==sep and depth==0:
            parts.append(s[start:i]); start=i+1
    parts.append(s[start:])
    return parts

def parse_stylesheet(css):
    css=remove_non_bang_comments(css)
    items=[]; i=0; n=len(css)
    while i<n:
        while i<n and css[i].isspace(): i+=1
        if i>=n: break
        if css.startswith('/*!', i):
            j=css.find('*/', i+3)
            if j<0: j=n-2
            items.append(('comment', css[i:j+2].strip()))
            i=j+2; continue
