            end=find_matching(css, i)
            content=css[i+1:end]
            items.append(('rule', pre, content))
            i=end+1
        elif found==';':
            items.append(('atrule', pre))
            i+=1
        else:
            if pre: items.append(('atrule', pre))
            break
