# ---------------- Normalization ----------------
NAMED_RGB={
 'black':(0,0,0,255),'white':(255,255,255,255),'red':(255,0,0,255),'green':(0,128,0,255),
 'blue':(0,0,255,255),'yellow':(255,255,0,255),'magenta':(255,0,255,255),'fuchsia':(255,0,255,255),
 'cyan':(0,255,255,255),'aqua':(0,255,255,255),'purple':(128,0,128,255),'gray':(128,128,128,255),'grey':(128,128,128,255),
 'orange':(255,165,0,255),'rebeccapurple':(102,51,153,255),'transparent':(0,0,0,0)
