def shortest_color(r,g,b,a=255):
    r=max(0,min(255,int(round(r)))); g=max(0,min(255,int(round(g)))); b=max(0,min(255,int(round(b)))); a=max(0,min(255,int(round(a))))
    if a==255:
        if (r,g,b)==(255,0,0): return 'red'
        if (r,g,b)==(0,128,0): return 'green'
