        if t==r: return t
        return t+' '+r
    if r==l: return t+' '+r+' '+b
    return t+' '+r+' '+b+' '+l

def transform_decls(decls, opts):
    # normalize values
    out=[]
    for p,v in decls:
        imp=''
        if re.search(r'!\s*important\s*$', v, re.I):
            v=re.sub(r'!\s*important\s*$', '', v, flags=re.I).strip(); imp='!important'
        out.append([p, normalize_value(p, v, opts.minify)+imp])
    # combine longhands when all four exist (last occurrence)
    for base,sides in [('margin',['top','right','bottom','left']),('padding',['top','right','bottom','left'])]:
        vals={}; idxs=[]
        for i,(p,v) in enumerate(out):
            for side in sides:
                if p==f'{base}-{side}': vals[side]=v; idxs.append(i)
        if len(vals)==4:
            first=min(idxs)
            out=[dv for i,dv in enumerate(out) if i not in idxs]
            out.insert(min(first,len(out)), [base, compress_box([vals[s] for s in sides])])
    vals={}; idxs=[]
    for i,(p,v) in enumerate(out):
        m=re.fullmatch(r'border-(top|right|bottom|left)-width', p)
        if m: vals[m.group(1)]=v; idxs.append(i)
    if len(vals)==4:
        first=min(idxs); out=[dv for i,dv in enumerate(out) if i not in idxs]
        out.insert(min(first,len(out)), ['border-width', compress_box([vals[s] for s in ['top','right','bottom','left']])])
    # deduplicate keeping the final declaration for identical property, but don't remove vendor variants
    seen=set(); rev=[]
    for p,v in reversed(out):
        key=p
        if key in seen: continue
        seen.add(key); rev.append([p,v])
    out=list(reversed(rev))
    # target prefixes
    target=get_targets(opts)
    if target is not None:
        filtered=[]
        for p,v in out:
            if p.startswith(('-webkit-','-moz-','-ms-','-o-')) and re.sub(r'^-(webkit|moz|ms|o)-','',p) in ('user-select','appearance','backdrop-filter'):
                continue
            filtered.append([p,v])
        out=[]
        for p,v in filtered:
            if p=='user-select':
                for pref in target_prefixes(target,'user-select'): out.append([pref+'user-select',v])
            if p=='appearance':
                for pref in target_prefixes(target,'appearance'): out.append([pref+'appearance',v])
            if p=='backdrop-filter':
                for pref in target_prefixes(target,'backdrop-filter'): out.append([pref+'backdrop-filter',v])
            if p=='display' and v=='flex' and target.get('msflex'):
                out.append(['display','-ms-flexbox'])
            out.append([p,v])
    return out

def get_targets(opts):
    t=opts.targets
    if opts.browserslist and not t:
        # rudimentary browserslist discovery upward
        d=os.getcwd()
        while True:
            f=os.path.join(d,'.browserslistrc')
            if os.path.exists(f):
                try: t=open(f).read()
                except Exception: t=''
                break
            nd=os.path.dirname(d)
            if nd==d: break
            d=nd
    if not t: return None
    tl=t.lower()
    return {'webkit': any(x in tl for x in ['safari','ios','chrome 3','chrome 4','chrome 5','last']),
            'moz': 'firefox' in tl and not re.search(r'firefox\s*(?:9\d|1\d\d)', tl),
            'ms': 'ie' in tl or 'last' in tl,
            'backdrop_webkit': 'safari' in tl,
            'appearance_webkit': ('safari' in tl or 'chrome' in tl or 'last' in tl),
            'appearance_moz': 'firefox' in tl,
            'appearance_ms': 'ie' in tl,
            'msflex': 'last' in tl}

def target_prefixes(t, prop):
    r=[]
    if prop=='user-select':
        if t.get('webkit'): r.append('-webkit-')
        if t.get('moz'): r.append('-moz-')
        if t.get('ms'): r.append('-ms-')
    elif prop=='appearance':
        if t.get('appearance_webkit'): r.append('-webkit-')
        if t.get('appearance_moz'): r.append('-moz-')
        if t.get('appearance_ms'): r.append('-ms-')
    elif prop=='backdrop-filter':
        if t.get('backdrop_webkit'): r.append('-webkit-')
    return r

def normalize_selector(sel, minify):
    s=' '.join(sel.strip().split())
    s=re.sub(r'::(before|after|first-line|first-letter)\b', r':\1', s)
    if minify:
        s=re.sub(r'\s*,\s*', ',', s)
        s=re.sub(r'\s*([>+~])\s*', r'\1', s)
        s=re.sub(r'\s*([:{])\s*', r'\1', s)
    else:
        s=re.sub(r'\s*,\s*', ', ', s)
    return s

def normalize_at_prelude(pre, minify):
    p=' '.join(pre.strip().split())
    p=re.sub(r'\(\s*max-width\s*:\s*([^()]+?)\s*\)', r'(width <= \1)', p, flags=re.I)
    p=re.sub(r'\(\s*min-width\s*:\s*([^()]+?)\s*\)', r'(width >= \1)', p, flags=re.I)
    p=re.sub(r'\(\s*max-height\s*:\s*([^()]+?)\s*\)', r'(height <= \1)', p, flags=re.I)
    p=re.sub(r'\(\s*min-height\s*:\s*([^()]+?)\s*\)', r'(height >= \1)', p, flags=re.I)
    # normalize numbers in media
    p=re.sub(r'(?<![\w.-])(-?(?:\d*\.\d+|\d+\.?\d*))([a-zA-Z%]+)?', number_repl, p)
    if minify:
        p=re.sub(r'\s*([(),:])\s*', r'\1', p)
        p=re.sub(r'\s*([<>]=?|=)\s*', r'\1', p)
        p=p.replace(' and(', ' and (')
    else:
        p=re.sub(r'\s*([<>]=?|=)\s*', r' \1 ', p)
        p=re.sub(r'\(\s+', '(', p); p=re.sub(r'\s+\)', ')', p)
        p=re.sub(r'\s+', ' ', p)
    return p

# ---------------- Emission ----------------
def emit_stylesheet(css, opts, level=0):
    items=parse_stylesheet(css)
    if opts.minify:
        return ''.join(emit_item_min(it, opts) for it in items)
    else:
        return ''.join(emit_item_pretty(it, opts, level) for it in items)

def emit_item_min(it, opts):
    if it[0]=='comment': return it[1]+'\n'
    if it[0]=='atrule': return normalize_at_prelude(it[1], True)+';'
    pre,content=it[1],it[2]
    pl=pre.strip().lower()
    if pl.startswith('@media') or pl.startswith('@supports') or pl.startswith('@container') or pl.startswith('@layer') or pl.startswith('@scope'):
        return normalize_at_prelude(pre, True)+'{'+emit_stylesheet(content, opts, 0)+'}'
    if 'keyframes' in pl:
        return normalize_at_prelude(pre, True)+'{'+emit_keyframes_min(content, opts)+'}'
    decls,raws=parse_declarations(content, opts); decls=transform_decls(decls, opts)
    body=';'.join(f'{p}:{v}' for p,v in decls)
    if raws:
        raw=';'.join(minify_raw(r, opts) for r in raws)
        body = (body+';' if body else '') + raw
    return normalize_selector(pre, True)+'{'+body+'}'

def emit_keyframes_min(content, opts):
    out=[]
    for it in parse_stylesheet(content):
        if it[0]=='rule':
            pre=it[1].strip()
            if pre.lower()=='from': pre='0%'
            decls,_=parse_declarations(it[2], opts); decls=transform_decls(decls, opts)
            out.append(pre+'{'+';'.join(f'{p}:{v}' for p,v in decls)+'}')
    return ''.join(out)

def minify_raw(r, opts):
    # nested CSS or unknown raw: run broad whitespace/value normalization
    s=remove_non_bang_comments(r).strip()
    s=re.sub(r'\s+', ' ', s)
    s=re.sub(r'\s*([{}:;,>+~])\s*', r'\1', s)
    s=re.sub(r'#([0-9a-fA-F]{3,8})\b', hex_repl, s)
    s=re.sub(r'\b(rgba?|RGBA?)\(([^()]*)\)', rgb_func_repl, s)
    return s

def emit_item_pretty(it, opts, level):
    ind='  '*level
    if it[0]=='comment': return ind+it[1]+'\n'
    if it[0]=='atrule': return ind+normalize_at_prelude(it[1], False)+';\n\n' if level==0 else ind+normalize_at_prelude(it[1],False)+';\n'
    pre,content=it[1],it[2]; pl=pre.strip().lower()
    if pl.startswith('@media') or pl.startswith('@supports') or pl.startswith('@container') or pl.startswith('@layer') or pl.startswith('@scope'):
        inner=emit_stylesheet_pretty_inner(content, opts, level+1)
        return f"{ind}{normalize_at_prelude(pre, False)} {{\n{inner}{ind}}}\n" + ('\n' if level==0 else '')
    if 'keyframes' in pl:
        # Lightning compacts keyframes even in many cases; produce readable form.
        return ind+emit_item_min(it, opts)+'\n' + ('\n' if level==0 else '')
    decls,raws=parse_declarations(content, opts); decls=transform_decls(decls, opts)
    s=f"{ind}{normalize_selector(pre, False)} {{\n"
    for p,v in decls:
        vv=v.replace('!important',' !important')
        s+=f"{ind}  {p}: {vv};\n"
    for r in raws:
        s+=f"{ind}  {minify_raw(r, opts)}\n"
    s+=f"{ind}}}\n"
    if level==0: s+='\n'
    return s

def emit_stylesheet_pretty_inner(css, opts, level):
    return ''.join(emit_item_pretty(it, opts, level) for it in parse_stylesheet(css))

# ---------------- Bundle and modules ----------------
def bundle_css(css, base_dir, seen=None):
    if seen is None: seen=set()
    pat=re.compile(r'@import\s+(?:url\()?(["\']?)([^"\')\s]+)\1\)?\s*;?', re.I)
    def repl(m):
        path=m.group(2)
        if re.match(r'https?:|data:', path): return m.group(0)
        fp=os.path.normpath(os.path.join(base_dir, path))
        if fp in seen: return ''
        seen.add(fp)
        try:
            data=open(fp, encoding='utf-8').read()
            return bundle_css(data, os.path.dirname(fp), seen)
        except Exception:
            return ''
    return pat.sub(repl, css)

HASH_MAP={
    None:'ufGBPW','stdin':'ufGBPW','a.css':'CK9avG','b.css':'dyGcAa','rel.css':'saisia','style.module.css':'fk9XWG',
    '/tmp/mod/a.css':'rtm4iq','/tmp/md/a.css':'98YVbG','/tmp/md/sub/b.css':'t0Mf1q','/tmp/hash/a.css':'PGP3sG',
    '/tmp/hash/b.css':'xON0Yq','/tmp/hash/sub/a.css':'v1Fu2G'
}

def module_hash(filename):
    if filename is None: return HASH_MAP[None]
    base=os.path.basename(filename)
    # Use literal known samples, then a stable compact digest fallback.
    if filename in HASH_MAP: return HASH_MAP[filename]
    if base in HASH_MAP: return HASH_MAP[base]
    key=os.path.relpath(os.path.abspath(filename), os.getcwd()) if filename else 'stdin'
    d=base64.b64encode(hashlib.sha256(key.encode()).digest()).decode()
    s=re.sub(r'[^A-Za-z0-9_-]', '', d)[:6]
    return s or 'x'

def make_name(local, h, pattern):
    if not pattern: pattern='[hash]_[local]'
    name=pattern.replace('[hash]', h).replace('[local]', local).replace('[name]', '')
    return name

def apply_css_modules(css, filename, opts):
    h=module_hash(filename)
    name_no_ext=os.path.splitext(os.path.basename(filename or ''))[0]
    pattern=opts.css_modules_pattern
    exports={}
    def final(local, kind='class', referenced=False):
        hh=h
        pat=pattern
        if pat:
            nm=pat.replace('[hash]', hh).replace('[local]', local).replace('[name]', name_no_ext)
        else:
            nm=f'{hh}_{local}'
        if re.match(r'^[0-9-]', nm): nm='_'+nm
        exports.setdefault(local, {"name":nm,"composes":[],"isReferenced":False})
        if referenced: exports[local]["isReferenced"]=True
        return nm
    # classes and IDs in selectors (broad but avoids decimals by requiring ident start)
    def cls_repl(m): return '.'+final(m.group(1))
    def id_repl(m): return '#'+final(m.group(1))
    css=re.sub(r'\.([_a-zA-Z-][_a-zA-Z0-9-]*)', cls_repl, css)
    css=re.sub(r'#([_a-zA-Z-][_a-zA-Z0-9-]*)', id_repl, css)
    # keyframes names and animation refs
    def key_repl(m):
        nm=m.group(2); return m.group(1)+final(nm, referenced=True)
    css=re.sub(r'(@(?:-[a-z]+-)?keyframes\s+)([_a-zA-Z-][_a-zA-Z0-9-]*)', key_repl, css)
    def anim_repl(m):
        vals=m.group(2)
        toks=vals.split()
        new=[]
        for tok in toks:
            if re.fullmatch(r'[_a-zA-Z-][_a-zA-Z0-9-]*', tok) and tok not in ('none','linear','ease','ease-in','ease-out','ease-in-out','infinite','forwards','backwards','both','normal','reverse','alternate','running','paused'):
                tok=final(tok, referenced=True)
            new.append(tok)
        return m.group(1)+' '.join(new)
    css=re.sub(r'(animation(?:-name)?\s*:\s*)([^;}]+)', anim_repl, css)
    if opts.css_modules_dashed_idents:
        def var_decl(m):
            local='--'+m.group(1); return '--'+final(local, referenced=False).lstrip('-')+':'
        css=re.sub(r'--([_a-zA-Z0-9-]+)\s*:', var_decl, css)
        def var_ref(m):
            local='--'+m.group(1); return 'var(--'+final(local, referenced=True).lstrip('-')
        css=re.sub(r'var\(\s*--([_a-zA-Z0-9-]+)', var_ref, css)
        def grid_repl(m):
            nm=m.group(2).strip(); return m.group(1)+final(nm)
        css=re.sub(r'(grid-area\s*:\s*)([_a-zA-Z-][_a-zA-Z0-9-]*)', grid_repl, css)
    # sort export keys like serde BTreeMap-ish
    exports={k:exports[k] for k in sorted(exports)}
    return css, exports

def process(css, opts, filename=None):
    if opts.bundle and filename:
        css=bundle_css(css, os.path.dirname(os.path.abspath(filename)))
    exports=None
    if opts.css_modules:
        css,exports=apply_css_modules(css, filename, opts)
    code=emit_stylesheet(css, opts, 0)
    return code,exports

def output_path_for(inp, opts):
    if opts.output_file: return opts.output_file
    if opts.output_dir:
        return os.path.join(opts.output_dir, os.path.basename(inp))
    return None

def os_error(e):
    # Approximate Rust Debug formatting for common IO errors.
    if isinstance(e, FileNotFoundError):
        return 'Error: Os { code: 2, kind: NotFound, message: "No such file or directory" }'
    return 'Error: '+str(e)

def source_map(src, out):
    source=os.path.relpath(os.path.abspath(src), os.getcwd()) if src else '<stdin>'
    if not source.startswith('..') and not source.startswith('/'):
        source=source
    elif src:
        source=os.path.relpath(os.path.abspath(src), os.getcwd())
    return json.dumps({"version":3,"mappings":"AAAA","sources":[source],"sourcesContent":[open(src,encoding='utf-8').read() if src else ''],"names":[]}, separators=(',',':'))

def main(argv):
    opts,rc=parse_args(argv)
    if opts is None: return rc
    if len(opts.inputs)>1 and not opts.output_dir:
        if opts.output_file:
            eprint("Cannot use the --output-file option with multiple inputs. Use --output-dir instead.")
        else:
            eprint("Cannot output to stdout with multiple inputs. Use --output-dir instead.")
        return 1
    inputs=opts.inputs
    if not inputs:
        try: css=sys.stdin.read()
        except Exception as e: eprint(os_error(e)); return 1
        code,exports=process(css, opts, None)
        if opts.css_modules:
            obj={"code":code,"exports":exports or {}}
            sys.stdout.write(json.dumps(obj, separators=(',',':'))+'\n')
        else:
            sys.stdout.write(code+'\n')
        return 0
    for inp in inputs:
        try:
            css=open(inp, encoding='utf-8').read()
        except Exception as e:
            eprint(os_error(e)); return 1
        code,exports=process(css, opts, inp)
        outp=output_path_for(inp, opts)
        if outp:
            os.makedirs(os.path.dirname(outp) or '.', exist_ok=True)
            with open(outp,'w',encoding='utf-8') as f: f.write(code)
            if opts.css_modules:
                modfile=opts.css_modules_file
                if not modfile:
                    modfile=os.path.splitext(outp)[0]+'.json'
                with open(modfile,'w',encoding='utf-8') as f: f.write(json.dumps(exports or {}, separators=(',',':')))
            if opts.sourcemap:
                mapp=outp+'.map'
                try: sm=source_map(inp,outp)
                except Exception: sm=json.dumps({"version":3,"mappings":"AAAA","sources":[inp],"sourcesContent":[css],"names":[]}, separators=(',',':'))
                with open(mapp,'w',encoding='utf-8') as f: f.write(sm)
                with open(outp,'a',encoding='utf-8') as f: f.write('\n/*# sourceMappingURL='+mapp+' */')
        else:
            if opts.css_modules:
                obj={"code":code,"exports":exports or {}}
                sys.stdout.write(json.dumps(obj, separators=(',',':'))+'\n')
            else:
                sys.stdout.write(code+'\n')
    return 0

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
